// RFC 9457 Problem Details, with the WAS specification's error type registry
// (Appendix G). `type` URIs are what @interop/was-client's mapError dispatches
// on, so they are spelled exactly as @interop/storage-core publishes them.

const SPEC_URL = "https://w3id.org/pws";

export const ProblemTypes = {
  NOT_FOUND: `${SPEC_URL}#not-found`,
  INVALID_ID: `${SPEC_URL}#invalid-id`,
  ID_CONFLICT: `${SPEC_URL}#id-conflict`,
  RESERVED_ID: `${SPEC_URL}#reserved-id`,
  PRECONDITION_FAILED: `${SPEC_URL}#precondition-failed`,
  INVALID_REQUEST_BODY: `${SPEC_URL}#invalid-request-body`,
  INVALID_CURSOR: `${SPEC_URL}#invalid-cursor`,
  MISSING_CONTENT_TYPE: `${SPEC_URL}#missing-content-type`,
  MISSING_AUTHORIZATION: `${SPEC_URL}#missing-authorization`,
  INVALID_AUTHORIZATION_HEADER: `${SPEC_URL}#invalid-authorization-header`,
  CONTROLLER_MISMATCH: `${SPEC_URL}#controller-mismatch`,
  UNSUPPORTED_OPERATION: `${SPEC_URL}#unsupported-operation`,
  PAYLOAD_TOO_LARGE: `${SPEC_URL}#payload-too-large`,
  STORAGE_ERROR: `${SPEC_URL}#storage-error`,
  INTERNAL_ERROR: `${SPEC_URL}#internal-error`,
};

// An error the router turns into a problem+json response.
export class HttpProblem extends Error {
  constructor({ status, type, title, detail, headers }) {
    super(detail ?? title);
    this.name = "HttpProblem";
    this.status = status;
    this.type = type;
    this.title = title;
    this.detail = detail;
    this.headers = headers;
  }

  toJSON() {
    return {
      type: this.type,
      title: this.title,
      status: this.status,
      ...(this.detail !== undefined && { detail: this.detail }),
    };
  }
}

// The one answer for anything the caller may not see or that does not exist:
// the spec's maximum-privacy rule says an unauthorized request is
// indistinguishable from a missing target.
export const notFound = (detail) =>
  new HttpProblem({ status: 404, type: ProblemTypes.NOT_FOUND, title: "Not found", detail });

export const invalidId = (detail) =>
  new HttpProblem({ status: 400, type: ProblemTypes.INVALID_ID, title: "Invalid id", detail });

export const reservedId = (id) =>
  new HttpProblem({
    status: 409,
    type: ProblemTypes.RESERVED_ID,
    title: "Reserved id",
    detail: `"${id}" is a reserved path segment and cannot be used as an id.`,
  });

export const idConflict = (detail) =>
  new HttpProblem({ status: 409, type: ProblemTypes.ID_CONFLICT, title: "Id conflict", detail });

export const preconditionFailed = (detail) =>
  new HttpProblem({
    status: 412,
    type: ProblemTypes.PRECONDITION_FAILED,
    title: "Precondition failed",
    detail,
  });

export const invalidRequestBody = (detail) =>
  new HttpProblem({
    status: 400,
    type: ProblemTypes.INVALID_REQUEST_BODY,
    title: "Invalid request body",
    detail,
  });

export const invalidCursor = (detail) =>
  new HttpProblem({ status: 400, type: ProblemTypes.INVALID_CURSOR, title: "Invalid cursor", detail });

export const missingContentType = () =>
  new HttpProblem({
    status: 400,
    type: ProblemTypes.MISSING_CONTENT_TYPE,
    title: "Missing Content-Type",
    detail: "A request with a body must carry a Content-Type header.",
  });

export const missingAuthorization = () =>
  new HttpProblem({
    status: 401,
    type: ProblemTypes.MISSING_AUTHORIZATION,
    title: "Missing authorization",
    detail: "This operation requires a signed capability invocation.",
  });

export const invalidAuthorizationHeader = (detail) =>
  new HttpProblem({
    status: 400,
    type: ProblemTypes.INVALID_AUTHORIZATION_HEADER,
    title: "Invalid authorization header",
    detail,
  });

export const controllerMismatch = (detail) =>
  new HttpProblem({
    status: 400,
    type: ProblemTypes.CONTROLLER_MISMATCH,
    title: "Controller mismatch",
    detail,
  });

// A reserved endpoint this server does not implement, or a method the
// endpoint does not take: the spec's 405.
export const methodNotAllowed = (allow = []) =>
  new HttpProblem({
    status: 405,
    type: ProblemTypes.UNSUPPORTED_OPERATION,
    title: "Method not allowed",
    headers: allow.length ? { Allow: allow.join(", ") } : undefined,
  });

export const internalError = () =>
  new HttpProblem({ status: 500, type: ProblemTypes.INTERNAL_ERROR, title: "Internal error" });
